<?php use SwimlogStandalone\Settings as S;use SwimLogEvaluation\Garmin_History_Jobs as Jobs;
$titles=array('garmin_activities'=>'Import Activities','garmin_measurements'=>'Import Measurements','garmin_history'=>'Historical Imports');$r=$configurationResult; ?>
<section class="calendar-panel workout-page" aria-labelledby="garmin-title"><div class="workout-page-heading"><h2 id="garmin-title"><?php echo esc_html($titles[$screen]); ?></h2><a class="control" href="/?screen=garmin_setup">Garmin Setup</a></div>
<?php if($configurationError): ?><p role="alert"><?php echo esc_html($configurationError->get_error_message()); ?></p><?php endif; ?>
<?php if($screen==='garmin_activities'):$operation='activities_browse';require __DIR__.'/garmin-form-start.php'; ?>
<div class="plan-field"><label for="activity-start">Activity start date</label><input id="activity-start" type="date" name="start" required value="<?php echo esc_attr(wp_date('Y-m-d',time()-7*DAY_IN_SECONDS)); ?>" max="<?php echo esc_attr(wp_date('Y-m-d')); ?>"></div><div class="plan-field"><label for="activity-end">Activity end date</label><input id="activity-end" type="date" name="end" required value="<?php echo esc_attr(wp_date('Y-m-d')); ?>" max="<?php echo esc_attr(wp_date('Y-m-d')); ?>"></div><fieldset><legend>Activities to find</legend><?php foreach(S::activities($owner)as$key=>$label): ?><label class="setting-check"><input type="checkbox" name="types[]" value="<?php echo esc_attr($key); ?>" <?php checked($key,'lap_swimming'); ?>><?php echo esc_html($label); ?></label><?php endforeach; ?></fieldset><p>Up to 30 days per request and 100 returned activities. Use Historical Imports for longer ranges or complete background discovery.</p><button>Find activities</button></form>
<?php if(isset($r['activities'])):$operation='activities_import';require __DIR__.'/garmin-form-start.php'; ?><input type="hidden" name="selection_token" value="<?php echo esc_attr($r['selection_token']); ?>"><fieldset><legend>Select activities to import (maximum 25)</legend><?php if(!$r['activities']): ?><p>No matching activities returned.</p><?php endif;foreach($r['activities']as$a): ?><label class="setting-check activity-choice"><input type="checkbox" name="activity_ids[]" value="<?php echo esc_attr($a['id']); ?>"><span><?php echo esc_html($a['date'].' · '.$a['name'].' · '.$a['type'].($a['distance']===null?'':' · '.number_format_i18n($a['distance'],1).' m')); ?></span></label><?php endforeach; ?></fieldset><div class="plan-field"><label for="activity-location">Open-water location (optional)</label><select id="activity-location" name="location_id"><option value="0">Use existing location rules</option><?php foreach(\SwimLogEvaluation\Location::all_for_user($owner)as$loc): ?><option value="<?php echo esc_attr($loc->id); ?>"><?php echo esc_html($loc->name); ?></option><?php endforeach; ?></select></div><button>Import selected activities</button></form><?php endif; ?>
<?php if(isset($r['activity_results'])): ?><div class="entry-compare"><table><thead><tr><th>Activity</th><th>Outcome</th></tr></thead><tbody><?php foreach($r['activity_results']as$out): ?><tr><td><?php echo esc_html($out['activity']); ?></td><td><?php echo esc_html($out['status']); ?><?php if(!empty($out['workout_id'])&&\SwimLogEvaluation\Workout::get_for_user($out['workout_id'],$owner)): ?> <a href="<?php echo esc_url('/?workout='.$out['workout_id']); ?>">View workout</a><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?><p><a href="/?screen=import">Review pending workout matches</a></p>
<?php elseif($screen==='garmin_measurements'):$operation='measurements_import';require __DIR__.'/garmin-form-start.php'; ?>
<?php foreach(array('start'=>'Measurement start date','end'=>'Measurement end date')as$key=>$label): ?><div class="plan-field"><label for="measure-<?php echo esc_attr($key); ?>"><?php echo esc_html($label); ?></label><input id="measure-<?php echo esc_attr($key); ?>" name="<?php echo esc_attr($key); ?>" type="date" required value="<?php echo esc_attr(wp_date('Y-m-d')); ?>" max="<?php echo esc_attr(wp_date('Y-m-d')); ?>"></div><?php endforeach; ?><fieldset><legend>Private measurement categories</legend><?php foreach(S::measurements()as$key=>$label): ?><label class="setting-check"><input type="checkbox" name="categories[]" value="<?php echo esc_attr($key); ?>"><?php echo esc_html($label); ?></label><?php endforeach; ?></fieldset><p>Maximum seven calendar days per request. Weight/BMI and SpO2 provider summaries remain private. Existing records are preserved on failed or unattempted requests.</p><button>Import measurements</button></form>
<?php if(isset($r['measurement_results'])): ?><div class="entry-compare"><table><thead><tr><th>Date / category</th><th>Outcome</th><th>Readings</th><th>Daily records</th></tr></thead><tbody><?php foreach($r['measurement_results']as$out): ?><tr><td><?php echo esc_html($out['date'].' · '.$out['category']); ?></td><td><?php echo esc_html($out['status']); ?></td><td><?php echo esc_html('Added '.$out['added'].'; updated '.$out['updated'].'; skipped '.$out['skipped'].'; failed '.$out['failed']); ?></td><td><?php echo esc_html('Added '.$out['reports_added'].'; updated '.$out['reports_updated'].'; skipped '.$out['reports_skipped']); ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
<?php else:$operation='history_start';require __DIR__.'/garmin-form-start.php'; ?>
<?php foreach(array('start'=>'Historical start date','end'=>'Historical end date')as$key=>$label): ?><div class="plan-field"><label for="history-<?php echo esc_attr($key); ?>"><?php echo esc_html($label); ?></label><input id="history-<?php echo esc_attr($key); ?>" name="<?php echo esc_attr($key); ?>" type="date" required max="<?php echo esc_attr(wp_date('Y-m-d')); ?>"></div><?php endforeach; ?><fieldset><legend>Historical categories</legend><?php $cats=S::measurements();if(current_user_can('swimlog_upload_workouts'))$cats=S::activities($owner)+$cats;foreach($cats as$key=>$label): ?><label class="setting-check"><input type="checkbox" name="categories[]" value="<?php echo esc_attr($key); ?>"><?php echo esc_html($label); ?></label><?php endforeach; ?></fieldset><p>Dates are inclusive. One unfinished job per swimmer. Work continues through existing WordPress cron jobs after this page closes; pausing or cancelling preserves imported records.</p><button>Start historical import</button></form>
<?php $jobId=$_GET['job']??null;$offset=$_GET['offset']??'0';$filter=$_GET['filter']??'all';
if(($jobId!==null&&(!is_string($jobId)||!preg_match('/^[a-f0-9]{32}$/D',$jobId)))||!is_string($offset)||!preg_match('/^[0-9]{1,7}$/D',$offset)||!is_string($filter)||!in_array($filter,array('all','failed','review'),true)): ?><p role="alert">Choose a valid job and result page.</p><?php else:$job=Jobs::get($jobId);if(is_array($job)): ?>
<section class="history-status"><h3><?php echo esc_html($job['start'].' — '.$job['end']); ?></h3><p role="status">Job status: <?php echo esc_html($job['status']); ?></p><p><?php echo esc_html('Unfinished items: '.count($job['ready']).'; failed items: '.count($job['failed'])); ?></p><dl class="workout-metrics"><?php foreach($job['counts']as$key=>$value): ?><div><dt><?php echo esc_html(ucwords(str_replace('_',' ',$key))); ?></dt><dd><?php echo esc_html((int)$value); ?></dd></div><?php endforeach; ?></dl>
<?php $next=Jobs::next($job['id']);if($next): ?><p>Next background task: <?php echo esc_html(wp_date('Y-m-d H:i',$next,wp_timezone())); ?></p><?php endif; ?>
<div class="plan-actions"><?php $controls=array();if(in_array($job['status'],array('queued','running','waiting'),true))$controls['pause']='Pause';if(in_array($job['status'],array('paused','blocked'),true)||(!$next&&in_array($job['status'],array('queued','running','waiting'),true)))$controls['resume']='Resume / repair schedule';if(!in_array($job['status'],array('completed','completed_with_errors','cancelled'),true))$controls['cancel']='Cancel — keep imported records';if($job['status']==='completed_with_errors')$controls['retry']='Retry failed items';foreach($controls as$key=>$label):$operation='history_'.$key;require __DIR__.'/garmin-form-start.php'; ?><input type="hidden" name="job" value="<?php echo esc_attr($job['id']); ?>"><button><?php echo esc_html($label); ?></button></form><?php endforeach; ?></div>
<p><a class="control" href="<?php echo esc_url('/?screen=garmin_history&job='.$job['id'].'&offset='.(int)$offset.'&filter='.$filter); ?>">Refresh job status</a></p>
<nav class="event-filters" aria-label="Historical result filters"><?php foreach(array('all'=>'All results','failed'=>'Failed items','review'=>'Needs review')as$key=>$label): ?><a class="control" href="<?php echo esc_url('/?screen=garmin_history&job='.$job['id'].'&filter='.$key); ?>"><?php echo esc_html($label); ?></a><?php endforeach; ?></nav>
<?php $units=Jobs::units($job['id'],(int)$offset,$filter); ?><div class="entry-compare" tabindex="0" role="region" aria-label="Historical results"><table><thead><tr><th>Work item</th><th>Status</th><th>Review</th></tr></thead><tbody><?php foreach($units['items']??array()as$unit): ?><tr><td><?php echo esc_html(($unit['data']['date']??($unit['data']['cursor']['day']??'')).' · '.$unit['kind']); ?></td><td><?php echo esc_html($unit['status']); ?></td><td><?php if($unit['status']==='review'&&$unit['kind']==='activity'): ?><a href="/?screen=garmin_activities">Find activity / assign location</a> · <a href="/?screen=import">Review pending import</a><?php endif;foreach($unit['outcomes']??array()as$key=>$out): ?><p><?php echo esc_html($key.': '.($out['status']??'')); ?></p><?php endforeach; ?></td></tr><?php endforeach; ?></tbody></table></div>
<nav class="event-filters" aria-label="Historical result pages"><?php if((int)$offset>0): ?><a class="control" href="<?php echo esc_url('/?screen=garmin_history&job='.$job['id'].'&filter='.$filter.'&offset='.max(0,(int)$offset-20)); ?>">Previous results</a><?php endif;if((int)$offset+20<($units['total']??0)): ?><a class="control" href="<?php echo esc_url('/?screen=garmin_history&job='.$job['id'].'&filter='.$filter.'&offset='.((int)$offset+20)); ?>">Next results</a><?php endif; ?></nav></section>
<?php elseif($jobId!==null): ?><p role="alert">Historical job not found.</p><?php endif;endif; ?>
<h3>Recent jobs</h3><ul><?php foreach(Jobs::recent()as$recent): ?><li><a href="<?php echo esc_url('/?screen=garmin_history&job='.$recent['id']); ?>"><?php echo esc_html($recent['start'].' — '.$recent['end'].' · '.$recent['status']); ?></a></li><?php endforeach; ?></ul><?php endif; ?></section>
